// Portable payment handlers: Deno in Supabase, Node's test runner locally.
const DEFAULT_APP_URL = 'https://urbanfold.github.io/property-survey/';
const PRODUCT = 'urbanfold_additional_survey';
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const SESSION = /^cs_(test|live)_[A-Za-z0-9]+$/;
const INTENT = /^pi_[A-Za-z0-9]+$/;

function settings(env) {
  const app = new URL(env('APP_URL') || DEFAULT_APP_URL);
  if (app.protocol !== 'https:' || app.search || app.hash || !app.pathname.endsWith('/')) throw new Error('Invalid application URL');
  const mode = env('SURVEY_PAYMENTS_MODE') || 'disabled';
  const key = env('STRIPE_SECRET_KEY') || '';
  const enabled = (mode === 'test' && key.startsWith('sk_test_')) || (mode === 'live' && key.startsWith('sk_live_'));
  return { app, mode, key, enabled, url: env('SUPABASE_URL'), anon: env('SUPABASE_ANON_KEY'),
    service: env('SUPABASE_SERVICE_ROLE_KEY'), webhook: env('STRIPE_WEBHOOK_SECRET') };
}
function json(body, status = 200, origin = null) {
  const headers = { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' };
  if (origin) Object.assign(headers, { 'Access-Control-Allow-Origin': origin, 'Vary': 'Origin',
    'Access-Control-Allow-Headers': 'authorization, apikey, content-type, x-client-info',
    'Access-Control-Allow-Methods': 'POST, OPTIONS' });
  return new Response(JSON.stringify(body), { status, headers });
}
async function parsed(response) {
  try { return await response.json(); } catch { return null; }
}

export async function createCheckout(request, { env, fetcher = fetch }) {
  let config;
  try { config = settings(env); } catch { return json({ error: 'Payments are not configured yet.' }, 503); }
  const origin = request.headers.get('origin');
  const cors = origin === config.app.origin ? origin : null;
  if (origin && !cors) return json({ error: 'Origin not permitted.' }, 403);
  if (request.method === 'OPTIONS') return new Response(null, { status: 204, headers: {
    'Access-Control-Allow-Origin': config.app.origin, 'Access-Control-Allow-Headers': 'authorization, apikey, content-type, x-client-info',
    'Access-Control-Allow-Methods': 'POST, OPTIONS', 'Vary': 'Origin' } });
  if (request.method !== 'POST') return json({ error: 'Method not allowed.' }, 405, cors);
  if (!config.enabled || !config.url || !config.anon) return json({ error: 'Payments are not available yet. Please contact survey@urbanfold.uk.' }, 503, cors);
  const authorization = request.headers.get('authorization') || '';
  if (!/^Bearer \S+$/.test(authorization)) return json({ error: 'Please sign in before buying a survey.' }, 401, cors);
  try {
    const userResponse = await fetcher(config.url + '/auth/v1/user', { headers: { apikey: config.anon, authorization } });
    const user = await parsed(userResponse);
    if (!userResponse.ok || !UUID.test(user?.id || '')) return json({ error: 'Please sign in again.' }, 401, cors);
    const headers = { apikey: config.anon, authorization, 'Content-Type': 'application/json' };
    const allowanceResponse = await fetcher(config.url + '/rest/v1/rpc/get_survey_allowance', { method: 'POST', headers, body: '{}' });
    const allowance = await parsed(allowanceResponse);
    if (!allowanceResponse.ok) return json({ error: 'Your survey allowance could not be checked. Please try again.' }, 503, cors);
    if (allowance?.can_create) return json({ error: 'You already have a survey available. Return to My Surveys to use it.' }, 409, cors);
    let body;
    try { body = await request.json(); } catch { return json({ error: 'Invalid checkout request.' }, 400, cors); }
    if (!UUID.test(body?.attempt_id || '')) return json({ error: 'Invalid checkout request.' }, 400, cors);
    const success = config.app.href + '?payment=success&checkout_session_id={CHECKOUT_SESSION_ID}';
    const params = new URLSearchParams({ mode: 'payment', client_reference_id: user.id,
      success_url: success, cancel_url: config.app.href + '?payment=cancelled',
      // Payment methods are managed in Stripe Dashboard (current Checkout API).
      'line_items[0][quantity]': '1',
      'line_items[0][price_data][currency]': 'gbp', 'line_items[0][price_data][unit_amount]': '600',
      'line_items[0][price_data][product_data][name]': 'One additional Urbanfold property survey',
      'metadata[product]': PRODUCT, 'metadata[user_id]': user.id,
      'payment_intent_data[metadata][product]': PRODUCT, 'payment_intent_data[metadata][user_id]': user.id });
    if (user.email) params.set('customer_email', user.email);
    const stripeResponse = await fetcher('https://api.stripe.com/v1/checkout/sessions', { method: 'POST', headers: {
      Authorization: 'Bearer ' + config.key, 'Content-Type': 'application/x-www-form-urlencoded',
      // Version the changed request to avoid replaying the previous rejected payload.
      'Idempotency-Key': 'urbanfold-survey-v2-' + user.id + '-' + body.attempt_id }, body: params.toString() });
    const session = await parsed(stripeResponse);
    if (!stripeResponse.ok || !SESSION.test(session?.id || '')) return json({ error: 'Checkout could not be opened. Please return to My Surveys and try again.' }, 502, cors);
    const destination = new URL(session.url);
    if (destination.protocol !== 'https:' || destination.hostname !== 'checkout.stripe.com') throw new Error('Invalid checkout destination');
    return json({ url: destination.href, test_mode: config.mode === 'test' }, 200, cors);
  } catch {
    return json({ error: 'Checkout could not be confirmed. Please try again using the same purchase button.' }, 502, cors);
  }
}

export async function verifyStripeSignature(raw, header, secret, now = Date.now()) {
  if (!header || !secret) return false;
  const entries = header.split(',').map(part => part.trim().split('='));
  const timestamp = entries.find(([key]) => key === 't')?.[1];
  if (!/^\d+$/.test(timestamp || '') || Math.abs(now / 1000 - Number(timestamp)) > 300) return false;
  const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['verify']);
  for (const [label, value] of entries) {
    if (label !== 'v1' || !/^[a-f0-9]{64}$/i.test(value || '')) continue;
    const bytes = Uint8Array.from(value.match(/../g), byte => parseInt(byte, 16));
    if (await crypto.subtle.verify('HMAC', key, bytes, new TextEncoder().encode(timestamp + '.' + raw))) return true;
  }
  return false;
}

export async function stripeWebhook(request, { env, fetcher = fetch, now = Date.now }) {
  if (request.method !== 'POST') return json({ error: 'Method not allowed.' }, 405);
  let config;
  try { config = settings(env); } catch { return json({ error: 'Payment server is not configured.' }, 503); }
  if (!config.enabled || !config.service || !config.url || !config.webhook) return json({ error: 'Payment server is not configured.' }, 503);
  if (Number(request.headers.get('content-length')) > 1024 * 1024) return json({ error: 'Payload too large.' }, 413);
  const raw = await request.text();
  if (new TextEncoder().encode(raw).length > 1024 * 1024) return json({ error: 'Payload too large.' }, 413);
  if (!await verifyStripeSignature(raw, request.headers.get('stripe-signature'), config.webhook, now())) return json({ error: 'Invalid webhook signature.' }, 400);
  let event;
  try { event = JSON.parse(raw); } catch { return json({ error: 'Invalid event.' }, 400); }
  if (!event || typeof event !== 'object' || Array.isArray(event)) return json({ error: 'Invalid event.' }, 400);
  if (event.livemode !== (config.mode === 'live')) return json({ received: true, ignored: 'Different payment mode.' });
  const object = event.data?.object;
  const rpc = async (name, body) => {
    const response = await fetcher(config.url + '/rest/v1/rpc/' + name, { method: 'POST', headers: {
      apikey: config.service, Authorization: 'Bearer ' + config.service, 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
    if (!response.ok) throw new Error('Payment ledger update failed');
  };
  try {
    if (['checkout.session.completed', 'checkout.session.async_payment_succeeded'].includes(event.type)) {
      if (object?.metadata?.product !== PRODUCT) return json({ received: true, ignored: 'Different product.' });
      if (object.payment_status !== 'paid') return json({ received: true, pending: true });
      const intent = typeof object.payment_intent === 'string' ? object.payment_intent : object.payment_intent?.id;
      const buyer = object.metadata?.user_id;
      if (object.mode !== 'payment' || object.amount_total !== 600 || object.currency !== 'gbp' ||
          object.livemode !== event.livemode || !SESSION.test(object.id || '') || !INTENT.test(intent || '') ||
          !UUID.test(buyer || '') || object.client_reference_id !== buyer) return json({ error: 'Payment details do not match the survey purchase.' }, 400);
      await rpc('record_survey_purchase', { session_id: object.id, intent_id: intent, buyer_id: buyer,
        paid_amount: 600, paid_currency: 'gbp', is_live: event.livemode });
      return json({ received: true, test_mode: !event.livemode });
    }
    if ((event.type === 'charge.refunded' && object?.amount_refunded > 0) || event.type === 'charge.dispute.created') {
      let intent = typeof object?.payment_intent === 'string' ? object.payment_intent : object?.payment_intent?.id;
      if (!intent && typeof object?.charge === 'string') {
        const response = await fetcher('https://api.stripe.com/v1/charges/' + encodeURIComponent(object.charge), { headers: { Authorization: 'Bearer ' + config.key } });
        const charge = await parsed(response);
        if (!response.ok) throw new Error('Charge lookup failed');
        intent = typeof charge?.payment_intent === 'string' ? charge.payment_intent : charge?.payment_intent?.id;
      }
      if (!INTENT.test(intent || '')) return json({ received: true, ignored: 'No survey payment reference.' });
      await rpc('revoke_survey_purchase', { intent_id: intent, revocation_reason: event.type });
    }
    return json({ received: true });
  } catch { return json({ error: 'Payment acknowledgement could not be saved. Retry this webhook.' }, 500); }
}

Deno.serve((request) => stripeWebhook(request, { env: (name) => Deno.env.get(name) }));
